// ABOUTME: Property tests for the money arithmetic, generated by a seeded fast-check run so a
// ABOUTME: failure reproduces: the integer arithmetic is exact and reversible, a rational scaling
// ABOUTME: lands within the rounding rule the caller names, mixed currencies and over-precision are
// ABOUTME: refused, and a total no float could hold stays exact.

import * as fc from 'fast-check';
import { describe, expect, it } from 'vitest';

import {
  MAX_AMOUNT_MINOR,
  MoneyError,
  ROUNDING_MODES,
  add,
  compare,
  equals,
  fromMajor,
  fromMinor,
  isNegative,
  isZero,
  multiply,
  multiplyRational,
  multiplyRationalExact,
  negate,
  subtract,
  sum,
  toDecimalString,
  zero,
  type CurrencyCode,
  type Money,
  type RoundingMode,
} from '..';
const OPTIONS = { seed: 20261022, numRuns: 200 } as const;

/** The currencies the properties exercise: 2, 0 and 3 decimals. */
const CURRENCIES = ['KES', 'UGX', 'KWD', 'JPY', 'TZS', 'USD'] as const;

const currency = fc.constantFrom(...CURRENCIES);
/** An amount whose product with a small factor still fits the safe integer range. */
const smallAmount = fc.integer({ min: -1_000_000_000_000, max: 1_000_000_000_000 });
const amount = fc.integer({ min: -MAX_AMOUNT_MINOR, max: MAX_AMOUNT_MINOR });

function moneyOf(amountMinor: number, code: (typeof CURRENCIES)[number]): Money {
  return fromMinor(amountMinor, code);
}

/** The magnitude of a bigint, so a test can reason about a signed division without Math.abs. */
function magnitude(value: bigint): bigint {
  return value < 0n ? -value : value;
}

/** The refusal a call raised, or null when it did not raise one. */
function refusalOf(work: () => unknown): MoneyError | null {
  try {
    work();
    return null;
  } catch (error) {
    if (error instanceof MoneyError) return error;
    throw error;
  }
}

describe('the integer arithmetic is exact and reversible', () => {
  it('adds and subtracts back to where it started', () => {
    fc.assert(
      fc.property(currency, smallAmount, smallAmount, (code, left, right) => {
        const a = moneyOf(left, code);
        const b = moneyOf(right, code);
        expect(subtract(add(a, b), b)).toEqual(a);
        expect(subtract(add(a, b), a)).toEqual(b);
      }),
      OPTIONS
    );
  });

  it('adds commutatively and keeps every result a whole minor unit in range', () => {
    fc.assert(
      fc.property(currency, smallAmount, smallAmount, (code, left, right) => {
        const a = moneyOf(left, code);
        const b = moneyOf(right, code);
        expect(add(a, b)).toEqual(add(b, a));
        expect(Number.isSafeInteger(add(a, b).amount_minor)).toBe(true);
        expect(add(a, b).currency).toBe(code);
      }),
      OPTIONS
    );
  });

  it('negates as an involution and to a zero sum', () => {
    fc.assert(
      fc.property(currency, amount, (code, value) => {
        const a = moneyOf(value, code);
        expect(negate(negate(a))).toEqual(a);
        expect(isZero(add(a, negate(a)))).toBe(true);
      }),
      OPTIONS
    );
  });

  it('sums a list to the same total in any order', () => {
    fc.assert(
      fc.property(currency, fc.array(smallAmount, { minLength: 1, maxLength: 20 }), (code, values) => {
        const list = values.map((value) => moneyOf(value, code));
        const total = sum(list);
        expect(total).toEqual(sum([...list].reverse()));
        expect(total.amount_minor).toBe(values.reduce((running, value) => running + value, 0));
        expect(total).toEqual(list.reduce(add, zero(code)));
      }),
      OPTIONS
    );
  });

  it('orders by amount and agrees with equality', () => {
    fc.assert(
      fc.property(currency, smallAmount, smallAmount, (code, left, right) => {
        const a = moneyOf(left, code);
        const b = moneyOf(right, code);
        const expected = left < right ? -1 : left > right ? 1 : 0;
        expect(compare(a, b)).toBe(expected);
        expect(equals(a, b)).toBe(left === right);
      }),
      OPTIONS
    );
  });

  it('multiplies by a whole number exactly', () => {
    fc.assert(
      fc.property(currency, fc.integer({ min: -1_000_000, max: 1_000_000 }), fc.integer({ min: -9, max: 9 }), (code, value, factor) => {
        const a = moneyOf(value, code);
        // A product of zero is +0, where `value * factor` may be -0; the two are the same amount.
        const expected = value * factor === 0 ? 0 : value * factor;
        expect(multiply(a, factor).amount_minor).toBe(expected);
      }),
      OPTIONS
    );
  });
});

describe('a rational scaling obeys the rounding rule the caller names', () => {
  it('lands within half a minor unit under half_up, keeping the sign', () => {
    fc.assert(
      fc.property(
        currency,
        smallAmount,
        fc.integer({ min: -1000, max: 1000 }),
        fc.integer({ min: 1, max: 1000 }),
        (code, value, numerator, denominator) => {
          const a = moneyOf(value, code);
          const result = multiplyRational(a, numerator, denominator, 'half_up');
          const exact = BigInt(value) * BigInt(numerator);
          // |result - exact/denominator| <= 0.5, compared as integers: 2*|result*denominator - exact| <= denominator.
          expect(magnitude(BigInt(result.amount_minor) * BigInt(denominator) - exact) * 2n <= BigInt(denominator)).toBe(true);
          if (result.amount_minor !== 0) expect(isNegative(result)).toBe(exact < 0n);
        }
      ),
      OPTIONS
    );
  });

  it('rounds down towards zero and up away from zero, never more than one minor unit', () => {
    fc.assert(
      fc.property(
        currency,
        smallAmount,
        fc.integer({ min: -1000, max: 1000 }),
        fc.integer({ min: 1, max: 1000 }),
        (code, value, numerator, denominator) => {
          const a = moneyOf(value, code);
          const exact = BigInt(value) * BigInt(numerator);
          const down = multiplyRational(a, numerator, denominator, 'down');
          const up = multiplyRational(a, numerator, denominator, 'up');
          const downError = magnitude(BigInt(down.amount_minor) * BigInt(denominator) - exact);
          const upError = magnitude(BigInt(up.amount_minor) * BigInt(denominator) - exact);
          expect(downError < BigInt(denominator)).toBe(true);
          expect(upError < BigInt(denominator)).toBe(true);
          expect(magnitude(BigInt(down.amount_minor))).toBeLessThanOrEqual(magnitude(exact) / BigInt(denominator) + 1n);
          expect(magnitude(BigInt(up.amount_minor))).toBeGreaterThanOrEqual(magnitude(exact) / BigInt(denominator));
        }
      ),
      OPTIONS
    );
  });

  it('is exact when the division lands on a whole minor unit, whatever the mode', () => {
    fc.assert(
      fc.property(
        currency,
        smallAmount,
        fc.integer({ min: 1, max: 500 }),
        fc.integer({ min: 1, max: 50 }),
        (code, value, denominator, quotient) => {
          const numerator = denominator * quotient;
          const a = moneyOf(value, code);
          const expected = value * quotient;
          for (const mode of ROUNDING_MODES) {
            expect(multiplyRational(a, numerator, denominator, mode).amount_minor).toBe(expected);
          }
        }
      ),
      OPTIONS
    );
  });

  it('multiplyRationalExact refuses exactly when the scaling is not a whole minor unit', () => {
    fc.assert(
      fc.property(
        currency,
        smallAmount,
        fc.integer({ min: -1000, max: 1000 }),
        fc.integer({ min: 1, max: 1000 }),
        (code, value, numerator, denominator) => {
          const a = moneyOf(value, code);
          const exact = (BigInt(value) * BigInt(numerator)) % BigInt(denominator);
          const refusal = refusalOf(() => multiplyRationalExact(a, numerator, denominator));
          if (exact === 0n) {
            expect(refusal).toBeNull();
            expect(multiplyRationalExact(a, numerator, denominator).amount_minor).toBe(
              Number((BigInt(value) * BigInt(numerator)) / BigInt(denominator))
            );
          } else {
            expect(refusal?.code).toBe('not_exact');
          }
        }
      ),
      OPTIONS
    );
  });

  it('rounds a fraction of a minor unit under every named mode, and names them all', () => {
    const half = fromMinor(1, 'UGX'); // a 0-decimal currency, so 1/2 of a shilling is the boundary
    const expected: Record<RoundingMode, number> = {
      half_up: 1,
      half_down: 0,
      half_even: 0,
      up: 1,
      down: 0,
    };
    for (const mode of ROUNDING_MODES) {
      expect(multiplyRational(half, 1, 2, mode).amount_minor, mode).toBe(expected[mode]);
    }
    expect(ROUNDING_MODES.length).toBe(5);
  });
});

describe('no float decides an amount', () => {
  it('refuses a value a float computed, rather than reading it as cents', () => {
    expect(0.1 + 0.2).not.toBe(0.3);
    const refusal = refusalOf(() => fromMajor(0.1 + 0.2, 'KES'));
    expect(refusal?.code).toBe('over_precision');
    // The same values written as decimals are exact and add up.
    expect(add(fromMajor('0.1', 'KES'), fromMajor('0.2', 'KES')).amount_minor).toBe(30);
    expect(fromMajor('0.3', 'KES').amount_minor).toBe(30);
  });

  it('keeps a total a float would drift on exact', () => {
    // Ten shillings is 10 minor units; ten of them are exactly 100, where a float accumulation is not.
    const tenPence = Array.from({ length: 10 }, () => fromMajor('0.10', 'KES'));
    expect(Array.from({ length: 10 }, () => 0).reduce((running) => running + 0.1, 0)).not.toBe(1);
    expect(sum(tenPence).amount_minor).toBe(100);
    expect(toDecimalString(sum(tenPence))).toBe('1.00');

    // A large total where a float loses a cent: 90,071,992,547,409.90 + 0.01 is exact in minor
    // units, and the same sum in major-unit doubles lands on ...409.92.
    const exact = add(fromMinor(9007199254740990, 'KES'), fromMinor(1, 'KES'));
    expect(exact.amount_minor).toBe(9007199254740991);
    expect(toDecimalString(exact)).toBe('90071992547409.91');
    expect(String(90071992547409.9 + 0.01)).toBe('90071992547409.92');

    // 0.1 * 3 is not 0.3 in a float; in minor units the product is exact.
    expect(0.1 * 3).not.toBe(0.3);
    expect(multiply(fromMajor('0.1', 'KES'), 3).amount_minor).toBe(30);
  });

  it('refuses a result that would leave the safe integer range', () => {
    const largest = fromMinor(MAX_AMOUNT_MINOR, 'KES');
    expect(refusalOf(() => multiply(largest, 2))?.code).toBe('invalid_amount');
    expect(refusalOf(() => add(largest, largest))?.code).toBe('invalid_amount');
  });
});

describe('the boundaries refuse what the currency cannot hold', () => {
  it('refuses more precision than the currency has, rather than rounding it', () => {
    expect(refusalOf(() => fromMajor('1.005', 'KES'))?.code).toBe('over_precision');
    expect(refusalOf(() => fromMajor(1.005, 'KES'))?.code).toBe('over_precision');
  });

  it('accepts digits beyond the exponent when they are all zero', () => {
    expect(fromMajor('1.500', 'KES').amount_minor).toBe(150);
    expect(fromMajor('150000.00', 'UGX').amount_minor).toBe(150000);
    expect(fromMajor('1.000', 'KWD').amount_minor).toBe(1000);
  });

  it('refuses a fraction of a minor unit in a 0-decimal currency', () => {
    expect(refusalOf(() => fromMajor('150000.5', 'UGX'))?.code).toBe('over_precision');
    expect(refusalOf(() => fromMajor(0.5, 'UGX'))?.code).toBe('over_precision');
    expect(fromMajor('150000', 'UGX').amount_minor).toBe(150000);
  });

  it('reads a decimal string or a number to the same minor units', () => {
    fc.assert(
      fc.property(currency, amount, (code, value) => {
        const a = moneyOf(value, code);
        expect(fromMajor(toDecimalString(a), code)).toEqual(a);
        const text = toDecimalString(a);
        const scale = text.includes('.') ? text.length - text.indexOf('.') - 1 : 0;
        expect(scale).toBe(code === 'UGX' || code === 'JPY' ? 0 : code === 'KWD' ? 3 : 2);
      }),
      OPTIONS
    );
  });

  it('refuses an amount that is not a whole minor unit, a non-decimal string, or an unknown currency', () => {
    expect(refusalOf(() => fromMinor(1.5, 'KES'))?.code).toBe('invalid_amount');
    expect(refusalOf(() => fromMinor(Number.NaN, 'KES'))?.code).toBe('invalid_amount');
    expect(refusalOf(() => fromMajor('1,500.00', 'KES'))?.code).toBe('invalid_amount');
    expect(refusalOf(() => fromMajor('', 'KES'))?.code).toBe('invalid_amount');
    expect(refusalOf(() => fromMajor('1e5', 'KES'))?.code).toBe('invalid_amount');
    expect(refusalOf(() => fromMinor(0, 'XYZ' as unknown as CurrencyCode))?.code).toBe('unknown_currency');
  });
});

describe('two currencies in one operation are refused, never coerced', () => {
  it('refuses adding, subtracting and comparing different currencies', () => {
    fc.assert(
      fc.property(
        fc.constantFrom(...CURRENCIES),
        fc.constantFrom(...CURRENCIES),
        smallAmount,
        smallAmount,
        (leftCode, rightCode, left, right) => {
          const a = moneyOf(left, leftCode);
          const b = moneyOf(right, rightCode);
          const same = leftCode === rightCode;
          expect(refusalOf(() => add(a, b))?.code ?? null).toBe(same ? null : 'currency_mismatch');
          expect(refusalOf(() => subtract(a, b))?.code ?? null).toBe(same ? null : 'currency_mismatch');
          expect(refusalOf(() => compare(a, b))?.code ?? null).toBe(same ? null : 'currency_mismatch');
        }
      ),
      OPTIONS
    );
  });

  it('refuses summing a mixed list and refuses an empty one', () => {
    expect(refusalOf(() => sum([fromMinor(1, 'KES'), fromMinor(1, 'UGX')]))?.code).toBe('currency_mismatch');
    expect(refusalOf(() => sum([]))?.code).toBe('invalid_amount');
    expect(sum([fromMinor(1, 'KES')])).toEqual(fromMinor(1, 'KES'));
  });
});
